for a in p['assets']:
 id=a['id'];x,y=a['center'];gate=id=='qianmen';name='正阳门城楼'if gate else'正阳门箭楼';s={'id':id,'name':name,'subject':'三滴水灰瓦、朱红柱廊与城台券门'if gate else'四层箭窗、白色窗檐与北侧抱厦','methodLabel':'资料与实景参考重建','x':x,'y':y,'rotation':a['angle'],'bounds':a['bounds'],'sourceOsmIds':[a['osmId']],'maskPolygon':a['maskPolygon'],'plantingPolygon':a['plantingPolygon'],'span':1.10 if gate else .88,'height':a['dimensions'][2]/100,'groundHeight':.012,'viewOffset':[40,85,150],'author':'参考摄影：Christophe95、Pixor；建筑重建：本项目','license':'CC BY-SA 4.0','licenseUrl':'https://creativecommons.org/licenses/by-sa/4.0/','source':'public/assets/qianmen-detail/ATTRIBUTION.html','method':'保留 OSM 中心与朝向，按公开尺寸和照片重建。门洞、瓦垄、柱廊及箭窗为几何模型；局部尺寸与装饰为推定，非文物测绘。','detailView':{'label':'走近城楼柱廊'if gate else'走近箭窗与窗檐','x':x,'y':y,'height':.23 if gate else .22,'span':.37 if gate else .43,'offset':[.30,.27,.95]},'contextView':{'label':'正阳门城楼与箭楼','x':(p['assets'][0]['center'][0]+p['assets'][1]['center'][0])/2,'y':(p['assets'][0]['center'][1]+p['assets'][1]['center'][1])/2,'height':.12,'span':2.5,'offset':[35,130,170]},'relatedModels':[{'id':'qianmen-arrow'if gate else'qianmen','label':'查看箭楼'if gate else'查看城楼'}],'lods':{}}
 if not gate:s['parentPlace']='qianmen'
 for level in['preview','detail']:
  a0=json.loads((R/f'output/qianmen-detail/{id}-{level}.json').read_text());s['lods'][level]=f'public/assets/qianmen-detail/{id}-{level}.glb?v={a0["revision"]}'
