 s['plantingPolygon']=polygon;s['bounds']=[min(p[0]for p in polygon),min(p[1]for p in polygon),max(p[0]for p in polygon),max(p[1]for p in polygon)]
 m['assets']=[b for b in m['assets']if b['id']!=id]+[s]
